<?php
declare(strict_types=1);
use SeoControlCenter\Domain\Keywords\KeywordLocale;
use SeoControlCenter\Domain\Shared\DateRange;
use SeoControlCenter\Modules\Research\BrandMentionService;
$settings = $brands['settings']; $latest = $brands['latest']; $attempt = $brands['attempt'];
$locale = $settings?->locale ?? KeywordLocale::default();
$input = $old + ['brand' => $settings?->name ?? '', 'location' => $locale->locationCode, 'language' => $locale->languageCode, 'weekly' => $settings?->weekly ? '1' : '0'];
$base = '/projects/' . $project->publicId . '/ai-visibility/brand';
$pending = $attempt !== null && in_array($attempt->status, ['queued', 'processing'], true);
$platforms = ['chat_gpt' => 'ChatGPT · US / English', 'google' => 'Google AI · selected market'];
?>
<section class="card" id="brand-mentions"<?= $pending ? ' data-refresh-seconds="15"' : '' ?>>
<h2>Brand-name mentions</h2>
<p>Find your name in AI answers even when the answer does not cite your website. Domain-based results above remain separate.</p>
<p class="muted small"><?= $view->e(BrandMentionService::NOTICE) ?></p>
<details><summary>How brand-name tracking works</summary><ol><li>Enter the public name your customers use. Pick the Google market and language.</li><li>Save the settings, then request a paid check or explicitly enable weekly checks.</li><li>Review answer excerpts and source evidence to distinguish your brand from namesakes.</li><li>Compare completed checks for the same name and market. Changing either starts a separate series.</li></ol><p>ChatGPT data is US / English only. Names use the provider’s word matching in answer text; this is not an exact-phrase guarantee. Saving a name does not start a paid request. A check needs four requests, estimated at $<?= number_format($brands['cost'], 3) ?>; workspace budgets still apply. Provider errors and interrupted requests are not silently retried.</p></details>
<?php if ($canEdit): ?><details<?= $errors !== [] || $settings === null ? ' open' : '' ?>><summary>Brand settings</summary><form method="post" action="<?= $view->e($base) ?>" class="stack">
<?= $view->csrfField() ?>
<div class="field"><label for="brand-name">Public brand name</label><input type="text" id="brand-name" name="brand" maxlength="120" value="<?= $view->e(is_string($input['brand']) ? $input['brand'] : '') ?>"<?= $view->invalid($errors, 'brand', 'brand-name') ?>><?= $view->fieldError($errors, 'brand', 'brand-name') ?><p class="muted small">Leave blank to stop tracking. Previously stored history is retained.</p></div>
<div class="field-pair"><div class="field"><label for="brand-location">Google market</label><select id="brand-location" name="location"><?php foreach (KeywordLocale::LOCATIONS as $code => $label): ?><option value="<?= $code ?>"<?= (is_scalar($input['location']) ? (string) $input['location'] : '') === (string) $code ? ' selected' : '' ?>><?= $view->e($label) ?></option><?php endforeach; ?></select><?php if (isset($errors['location'])): ?><p role="alert"><?= $view->e($errors['location']) ?></p><?php endif; ?></div>
<div class="field"><label for="brand-language">Google language</label><select id="brand-language" name="language" data-market-country="brand-location" data-labs="<?= $view->e(\SeoControlCenter\Domain\Keywords\Markets::labsJson()) ?>"><?php foreach (KeywordLocale::LANGUAGES as $code => $label): ?><option value="<?= $view->e($code) ?>"<?= $input['language'] === $code ? ' selected' : '' ?>><?= $view->e($label) ?></option><?php endforeach; ?></select><?php if (isset($errors['language'])): ?><p role="alert"><?= $view->e($errors['language']) ?></p><?php endif; ?></div></div>
<label><input type="checkbox" name="weekly" value="1"<?= ($input['weekly'] ?? null) === '1' ? ' checked' : '' ?>> Run a separate paid brand-name check every week (about $<?= number_format($brands['cost'], 3) ?> per check)</label>
<button class="button button-primary">Save brand settings</button></form></details><?php endif; ?>
<?php if (!$brands['available']): ?><p class="notice">Connect DataForSEO under Integrations before checking mentions.</p><?php elseif (!$brands['featureOn']): ?><p class="notice">New checks are turned off on this installation.</p><?php elseif ($canRun && $settings !== null && $settings->name !== ''): ?><form method="post" action="<?= $view->e($base . '/fetch') ?>" class="actions"><?= $view->csrfField() ?><button class="button button-secondary">Check brand name · about $<?= number_format($brands['cost'], 3) ?></button></form><?php endif; ?>
<?php if ($attempt !== null): ?><p class="muted">Latest attempt: <?= $view->e($attempt->status) ?> · <?= $view->e($attempt->updatedAt) ?> UTC<?php if ($pending): ?> · <?= $attempt->step ?> of 4 requests recorded. After an interruption, review Jobs and spending; a new check is permitted after 24 hours.<?php endif; ?></p><?php if ($attempt->error !== null): ?><p class="notice"><?= $view->e($attempt->error) ?> A new paid check requires your request; partial data is not shown as a completed result.</p><?php endif; ?><?php endif; ?>
<?php if ($latest === null): ?><p>No completed brand-name check for this name and market yet.</p><?php else: ?>
<h3><?= $view->e($settings->name) ?></h3><p class="muted small">Latest complete result: <?= $view->e($latest->updatedAt) ?> UTC · Google market <?= $view->e($locale->key()) ?>. Up to 25 answer examples per platform, ordered by AI search volume.</p>
<div class="stat-grid"><?php foreach ($platforms as $platform => $label): ?><?php $metric = $latest->metrics[$platform] ?? null; ?><div class="stat"><h3><?= $view->e($label) ?></h3><p class="stat-value"><?= $metric === null ? 'Unavailable' : number_format($metric['mentions']) ?></p><p class="muted small">Name mentions · AI search volume <?= $metric === null || $metric['ai_search_volume'] === null ? 'unavailable' : number_format($metric['ai_search_volume']) ?></p></div><?php endforeach; ?></div>
<?php foreach ($platforms as $platform => $label): ?><details><summary>Answer examples · <?= $view->e($label) ?></summary><?php $answers = $latest->answers[$platform] ?? []; ?><?php if ($answers === []): ?><p>No answer examples returned.</p><?php else: ?><div class="table-scroll"><table class="table"><thead><tr><th scope="col">Question and answer excerpt</th><th scope="col">Source evidence</th><th scope="col" class="num">AI search volume</th></tr></thead><tbody><?php foreach ($answers as $answer): ?><tr><td><strong><?= $view->e($answer->question) ?></strong><p><?= $view->e($answer->excerpt ?? 'No answer excerpt supplied.') ?></p><p class="muted small">Provider response date: <?= $view->e($answer->lastSeen ?? 'unavailable') ?></p></td><td><?= $answer->sourceRank === null ? 'No project-domain citation in this sample' : 'Project-domain source rank ' . $answer->sourceRank ?><?php if ($answer->sourceUrl !== null): ?><p class="small"><?= $view->e($answer->sourceUrl) ?></p><?php endif; ?><p class="muted small"><?= $view->e(implode(', ', $answer->sources)) ?></p></td><td class="num"><?= $answer->aiSearchVolume === null ? 'Unavailable' : number_format($answer->aiSearchVolume) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></details><?php endforeach; ?>
<?php endif; ?>
</section>
<?php foreach ($platforms as $platform => $label): ?><?php $daily = []; foreach ($brands['history'] as $check) { if ($check->status === 'completed' && isset($check->metrics[$platform]) && !isset($daily[substr($check->updatedAt, 0, 10)])) { $daily[substr($check->updatedAt, 0, 10)] = (float) $check->metrics[$platform]['mentions']; } } ksort($daily); $series = []; foreach ($daily as $date => $value) { $series[] = [$date, $value]; } ?>
<?php if ($series !== []): ?><?= $view->partial('partials/line-chart', ['title' => 'Brand-name mentions · ' . $label, 'series' => $series, 'range' => new DateRange($series[0][0], $series[count($series) - 1][0]), 'wide' => true]) ?><?php endif; ?><?php endforeach; ?>
<?php if ($brands['history'] !== []): ?><section class="card"><h2>Brand check history</h2><p class="muted small">Most recent 12 attempts for this exact name and market. Charts use the latest completed check per UTC day; missing or failed checks are not zero.</p><div class="table-scroll"><table class="table"><thead><tr><th scope="col">Requested (UTC)</th><th scope="col">Status</th><th scope="col" class="num">ChatGPT</th><th scope="col" class="num">Google AI</th></tr></thead><tbody><?php foreach ($brands['history'] as $check): ?><tr><td><?= $view->e($check->createdAt) ?></td><td><?= $view->e($check->status) ?></td><?php foreach (array_keys($platforms) as $platform): ?><td class="num"><?= $check->status !== 'completed' || !isset($check->metrics[$platform]) ? '—' : number_format($check->metrics[$platform]['mentions']) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
